import{z as o,x as d,o as A,c as s,q as i,j as t,D as e,d as a,s as r,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"数据工程收束","description":"","frontmatter":{"title":"数据工程收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/de-map.md","filePath":"quant/de-map.md","lastUpdated":1791063341000}'),p={name:"quant/de-map.md"};function D(C,E,u,h,m,f){const n=d("Mermaid");return A(),s("div",null,[E[2]||(E[2]=i('<h1 id="数据工程收束" tabindex="-1">数据工程收束 <a class="header-anchor" href="#数据工程收束" aria-label="Permalink to &quot;数据工程收束&quot;">​</a></h1><div class="epigraph"><p>数据平台不是一堆表的集合，是一组被强制执行的时间约定：什么不可变、什么何时可知、什么按哪个版本被引用；约定松一寸，回测的数字就虚一尺。</p><footer>—— 据 Croushore and Stark, Journal of Econometrics, 2001；López de Prado, Advances in Financial Machine Learning, Wiley, 2018 整理</footer></div><p><a href="/quant/de-vendor-integration">上一课</a>把外部世界的契约收拢进平台边界，最后一段管道落定。本课收束全课程：把十课重排成一张地图，重申贯穿的口径，交还边界，指明下一门课从哪里接走。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>十课走完，要收的不是功能清单，而是三条容易走散的主线。<span class="marginnote">术语翻译：append-only（只增不改）就是账本只许贴新条、不许涂旧账——发现记错了，正确做法是补一条更正分录并注明原因，而不是擦掉重写。引擎守住这条不变量，数据的历史才可能被审计。</span>其一，存储与清洗单元给了数据的「本体」：引擎守住 append-only、分区、列式三条不变量，清洗把单日字节翻译成语义，公司行动把跨日界的调整做成事件链，版本化让改写走发布。其二，平台单元给了「使用」：点时库把任一决策日的知识集收成一个函数，分布式回测与性能优化让这个函数撑得起大规模实验，质量监控与供应商对接守住边界内外的契约。其三，两个单元被同一件事缝合：哈希——定义、数据版本、清洗规则的三元哈希，让「任何一个数字为什么是这个值」永远可答。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>收束的方法是应力测试般的重读：把十课压成一张地图与三问，往后每次平台变更、每个新数据集接入，都拿地图照一遍——接在哪条线上、动了哪条不变量、哈希哪一位要换。地图按读序重排：</p><ul><li><a href="/quant/de-tsdb-selection">时序数据库的选型</a>：查询形状定引擎，不变量先于性能。</li><li><a href="/quant/de-marketdata-cleaning">行情数据的清洗</a>：硬校验、定序去重、标记过滤、快照对账，逐段入账。</li><li><a href="/quant/de-corporate-action-deep">公司行动处理的深入</a>：因子独立成版本序列，四表联动。</li><li><a href="/quant/de-data-versioning">数据版本化</a>：不可变存储，修正走发布，实验钉三元哈希。</li><li><a href="/quant/de-pointintime-db">点时数据库的构建</a>：双时间轴表加唯一 as-of 函数，研究生产共用。</li><li><a href="/quant/de-distributed-backtest">分布式回测架构</a>：任务钉版本，无状态 worker，一致性由数据版本承担。</li><li><a href="/quant/de-backtest-perf">回测性能优化</a>：先归因再动手，每次提速过逐日对账。</li><li><a href="/quant/de-quality-monitoring">数据质量监控</a>：四层断言三档处置，研究教训沉淀为闸门。</li><li><a href="/quant/de-vendor-integration">供应商对接</a>：六项契约落纸，影子双跑后切换，第二来源做锚。</li></ul>',8)),(A(),t(l,null,{default:e(()=>[r(n,{id:"mermaid-66",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20BODY%5B%22%E5%AD%98%E5%82%A8%E4%B8%8E%E6%B8%85%E6%B4%97%EF%BC%9A%E6%95%B0%E6%8D%AE%E6%9C%AC%E4%BD%93%22%5D%0A%20%20%20%20ENG%5B%22%E6%97%B6%E5%BA%8F%E5%BA%93%E9%80%89%E5%9E%8B%EF%BC%9A%E4%B8%89%E6%9D%A1%E4%B8%8D%E5%8F%98%E9%87%8F%22%5D%20--%3E%20CLN%5B%22%E8%A1%8C%E6%83%85%E6%B8%85%E6%B4%97%EF%BC%9A%E5%8D%95%E6%97%A5%E8%AF%AD%E4%B9%89%22%5D%0A%20%20%20%20CLN%20--%3E%20CORP%5B%22%E5%85%AC%E5%8F%B8%E8%A1%8C%E5%8A%A8%EF%BC%9A%E4%BA%8B%E4%BB%B6%E9%93%BE%E5%9B%A0%E5%AD%90%22%5D%0A%20%20%20%20CORP%20--%3E%20VER%5B%22%E7%89%88%E6%9C%AC%E5%8C%96%EF%BC%9A%E4%B8%8D%E5%8F%AF%E5%8F%98%E4%B8%8E%E5%8F%91%E5%B8%83%22%5D%0A%20%20end%0A%20%20subgraph%20PLAT%5B%22%E5%B9%B3%E5%8F%B0%EF%BC%9A%E4%BD%BF%E7%94%A8%E4%B8%8E%E5%AE%88%E5%8D%AB%22%5D%0A%20%20%20%20PIT%5B%22%E7%82%B9%E6%97%B6%E5%BA%93%EF%BC%9A%E5%94%AF%E4%B8%80%20as-of%20%E5%87%BD%E6%95%B0%22%5D%20--%3E%20DIST%5B%22%E5%88%86%E5%B8%83%E5%BC%8F%E5%9B%9E%E6%B5%8B%EF%BC%9A%E4%BB%BB%E5%8A%A1%E9%92%89%E7%89%88%E6%9C%AC%22%5D%0A%20%20%20%20DIST%20--%3E%20PERF%5B%22%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%EF%BC%9A%E9%80%90%E6%97%A5%E5%AF%B9%E8%B4%A6%22%5D%0A%20%20%20%20PERF%20--%3E%20MON%5B%22%E8%B4%A8%E9%87%8F%E7%9B%91%E6%8E%A7%EF%BC%9A%E5%9B%9B%E5%B1%82%E6%96%AD%E8%A8%80%22%5D%0A%20%20%20%20MON%20--%3E%20VEN%5B%22%E4%BE%9B%E5%BA%94%E5%95%86%E5%AF%B9%E6%8E%A5%EF%BC%9A%E5%A5%91%E7%BA%A6%E5%8C%96%E8%BE%B9%E7%95%8C%22%5D%0A%20%20end%0A%20%20BODY%20--%3E%20PLAT%0A%20%20PLAT%20--%3E%20NEXT%5B%22%E5%9B%9E%E6%B5%8B%E6%A1%86%E6%9E%B6%E8%AF%BE%E7%A8%8B%E6%8E%A5%E8%B5%B0%E5%BC%95%E6%93%8E%E8%AE%BE%E8%AE%A1%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("把十课压成一个视角：平台 = 不变量 × 时间语义 × 契约。"),B("span",{class:"marginnote"},"直觉类比：整个平台像一座档案馆——不变量是「归档后的卷宗永不改页」，时间语义是「每份卷宗都盖着入库与生效两枚时间章」，契约是「借阅必须走登记窗口」。三件事齐了，多年后任何一份结论都能翻回当时那页原件；缺一件，就只能靠记忆和口碑。"),a("不变量由引擎与治理共同维持（append-only、分区、因子链、不可变版本），绕过不变量的捷径——就地更新、前复权存库、缓存漏版本——都在为未来的不可复现付利息。时间语义集中在双时间轴与唯一 as-of 函数上，平台的价值在于让「当时可知」成为可精确调用的对象，而不是研究者的记忆。契约贯穿内外：对内是每张表的质量契约与告警分级，对外是供应商的六项条款；契约不是文档，是被断言强制执行的行为。三者的次序也解释了课程排序：不变量先于时间语义（没有不可变存储就没有可靠的事务时间），时间语义先于契约（没有 as-of 函数就没有可对账的影子对比）。")],-1)),(A(),t(l,null,{default:e(()=>[r(n,{id:"mermaid-73",class:"mermaid",graph:"flowchart%20TD%0A%20%20NUM%5B%22%E5%9B%9E%E6%B5%8B%E9%87%8C%E7%9A%84%E4%B8%80%E4%B8%AA%E6%95%B0%E5%AD%97%22%5D%20--%3E%20H1%5B%22%E6%95%B0%E6%8D%AE%E7%89%88%E6%9C%AC%E5%93%88%E5%B8%8C%3A%20%E6%98%AF%E5%93%AA%E4%BB%BD%E5%AD%97%E8%8A%82%22%5D%0A%20%20NUM%20--%3E%20H2%5B%22%E5%AE%9A%E4%B9%89%20%2B%20%E6%B8%85%E6%B4%97%E8%A7%84%E5%88%99%E5%93%88%E5%B8%8C%3A%20%E6%8C%89%E5%93%AA%E6%9D%A1%E8%A7%84%E5%88%99%E7%AE%97%E5%87%BA%22%5D%0A%20%20NUM%20--%3E%20H3%5B%22as-of%20%E6%97%B6%E7%82%B9%3A%20%E5%BD%93%E6%97%B6%E5%8F%AF%E7%9F%A5%E7%9A%84%E7%9F%A5%E8%AF%86%E9%9B%86%22%5D%0A%20%20H1%20--%3E%20A%5B%22%E4%B8%89%E8%80%85%E7%9A%86%E9%92%89%20%E2%86%92%20%E9%80%90%E5%AD%97%E8%8A%82%E5%8F%AF%E9%87%8D%E5%BB%BA%22%5D%0A%20%20H2%20--%3E%20A%0A%20%20H3%20--%3E%20A%0A%20%20H1%20-.%20%22%E7%BC%BA%E4%B8%80%22%20.-%3E%20B%5B%22%E5%A4%8D%E7%8E%B0%E9%9D%A0%E8%BF%90%E6%B0%94%3A%20%E5%B7%AE%E5%BC%82%E6%97%A0%E6%B3%95%E5%BD%92%E5%9B%A0%22%5D%0A%20%20H2%20-.%20%22%E7%BC%BA%E4%B8%80%22%20.-%3E%20B%0A%20%20H3%20-.%20%22%E7%BC%BA%E4%B8%80%22%20.-%3E%20B%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=i('<p><span class="marginnote">贯穿口径一句话：研究里的每个数字都应能回答三个问题——哪份字节（数据版本）、哪条规则（定义与清洗哈希）、哪个知识集（as-of 时点）。三问皆答，复现是工程；有一问答不出，复现是运气。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>收束课不新增机制，边界重申三条。平台的承诺止于「数据配得上用途」：信号有没有效、因子是不是幸存者，仍由统计协议裁决，<span class="marginnote">常见误区：初学者容易以为「把数据平台建好，策略就自然赚钱了」。平台只保证你算出的每个数字可信、可复现——至于这个可信的数字对应的信号有没有 alpha，是统计协议和研究的问题。地基再结实，也不等于楼里一定有金子。</span>平台不背预测的锅。技术选型随生态漂移：引擎与表格式几年一换，不变量与时间语义却是稳定的，迁移带走的是约定而非实例。成本约束真实：vintage、双源、影子期的开销按研究价值分配，核心表全套、长尾表降级。深钻层到此为止：主干与这门平台的工程，构成下一阶段回测框架课程的全部前提——引擎设计从此建立在可信数据之上。本课程到此收束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一条本体线：选型不变量 → 单日清洗 → 公司行动事件链 → 版本化发布。</li><li>一条平台线：唯一 as-of 函数 → 分布式与性能 → 质量断言 → 供应商契约。</li><li>缝合线是三元哈希：定义、数据版本、清洗规则，任何数字可溯源到三者。</li><li>贯穿口径三问：哪份字节、哪条规则、哪个知识集；三问答不出，复现靠运气。</li><li>边界三条：不背预测的锅、约定比实例稳定、成本按研究价值分配。</li><li>出处：Croushore and Stark, <em>Journal of Econometrics</em>, 2001；López de Prado, <em>Advances in Financial Machine Learning</em>, Wiley, 2018；及本课程各课所引文献。</li></ul>',5))])}const q=o(p,[["render",D]]);export{c as __pageData,q as default};
